import math

def calculate_F(D_i, P_j):
    return math.floor(D_i / P_j)

def calculate_interference_I_i_j(D_i, P_j, C_j):
    F = calculate_F(D_i, P_j)
    if D_i >= F * P_j + C_j:
        # Deadline occurs while T_j is not executed (after F+1 jobs)
        return (F + 1) * C_j
    else:
        # Deadline occurs while T_j is executed (during F+1-th job)
        return D_i - F * (P_j - C_j)

import math

def calculate_dm_preemptions_N_L(L, task_set):
    N_L = 0
    for task_i in task_set:
        N_L += math.floor(L / task_i.P)
    return N_L
